/* amirsalmani/link — underline at 40%, going solid.
 *
 * Requires tokens.css. Never a colour change on hover: there is no accent hue
 * to change to (brand.md §2).
 */

.as-link {
  color: inherit;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: .22em;
  text-decoration-color: color-mix(in srgb, currentColor 40%, transparent);
  transition: text-decoration-color var(--fast) var(--ease-out), color var(--fast) var(--ease-out);
}
.as-link:hover, .as-link:focus-visible { color: var(--fg-accent); text-decoration-color: currentColor; }
.as-link:focus-visible { outline: 2px solid var(--fg-accent); outline-offset: 3px; border-radius: 2px; }
